mapper.select:
SELECT h.*, m.name AS member_name FROM card_reissue_history h JOIN member m ON h.member_id = m.member_id
AND h.reason = #{dto.reason}
AND (h.old_card_number LIKE CONCAT('%', #{dto.keyword}, '%') OR h.new_card_number LIKE CONCAT('%', #{dto.keyword}, '%') OR m.name LIKE CONCAT('%', #{dto.keyword}, '%'))
ORDER BY h.created_at DESC LIMIT #{dto.size} OFFSET #{dto.offset}

SELECT COUNT(*) FROM card_reissue_history h JOIN member m ON h.member_id = m.member_id
AND h.reason = #{dto.reason}
AND (h.old_card_number LIKE CONCAT('%', #{dto.keyword}, '%') OR h.new_card_number LIKE CONCAT('%', #{dto.keyword}, '%') OR m.name LIKE CONCAT('%', #{dto.keyword}, '%'))

SELECT * FROM card_reissue_history
WHERE member_id = #{memberId}
ORDER BY created_at DESC

SELECT * FROM card_reissue_history
WHERE old_card_id = #{oldCardId}
ORDER BY created_at DESC
